-- ---------- 2. 建表 ----------
-- 商品品类 (categories)，主键：category_id
CREATE TABLE categories (
    category_id NUMBER(10),
    category_name VARCHAR2(128),
    parent_category_id NUMBER(10)
);

-- 商品 (products)，主键：product_id
CREATE TABLE products (
    product_id NUMBER(10),
    product_name VARCHAR2(128),
    category_id NUMBER(10),
    brand VARCHAR2(128),
    price NUMBER(18,2),
    cost NUMBER(18,2),
    launch_date DATE,
    status VARCHAR2(128)
);

-- 门店 (stores)，主键：store_id
CREATE TABLE stores (
    store_id NUMBER(10),
    store_name VARCHAR2(128),
    city VARCHAR2(128),
    province VARCHAR2(128),
    region VARCHAR2(128),
    open_date DATE,
    status VARCHAR2(128),
    dept_id NUMBER(10)
);

-- 门店月度目标 (store_targets)，主键：store_id, target_month
CREATE TABLE store_targets (
    store_id NUMBER(10),
    target_month DATE,
    target_amt NUMBER(18,2),
    budget NUMBER(18,2)
);

-- 电商客户 (customers)，主键：customer_id
CREATE TABLE customers (
    customer_id NUMBER(10),
    customer_name VARCHAR2(128),
    gender VARCHAR2(128),
    birth_date DATE,
    city VARCHAR2(128),
    province VARCHAR2(128),
    register_date DATE,
    "level" VARCHAR2(128),
    status VARCHAR2(128),
    last_order_date DATE,
    order_cnt NUMBER(10),
    total_amt NUMBER(18,2)
);

-- 订单主表 (orders)，主键：order_id
CREATE TABLE orders (
    order_id NUMBER(10),
    customer_id NUMBER(10),
    store_id NUMBER(10),
    order_date DATE,
    status VARCHAR2(128),
    channel VARCHAR2(128),
    pay_amount NUMBER(18,2),
    discount_amount NUMBER(18,2)
);

-- 订单明细 (order_items)，主键：order_id, product_id
CREATE TABLE order_items (
    order_id NUMBER(10),
    product_id NUMBER(10),
    quantity NUMBER(10),
    amount NUMBER(18,2),
    price NUMBER(18,2)
);

-- 支付流水 (payments)，主键：payment_id
CREATE TABLE payments (
    payment_id NUMBER(10),
    order_id NUMBER(10),
    pay_method VARCHAR2(128),
    pay_amount NUMBER(18,2),
    pay_date DATE,
    pay_time DATE,
    status VARCHAR2(128)
);

-- 退款记录 (refunds)，主键：refund_id
CREATE TABLE refunds (
    refund_id NUMBER(10),
    order_id NUMBER(10),
    refund_amount NUMBER(18,2),
    refund_reason VARCHAR2(128),
    reason VARCHAR2(128),
    refund_date DATE,
    status VARCHAR2(128)
);

-- 物流运单 (shipments)，主键：shipment_id
CREATE TABLE shipments (
    shipment_id NUMBER(10),
    order_id NUMBER(10),
    carrier VARCHAR2(128),
    ship_date DATE,
    delivery_days NUMBER(10),
    province VARCHAR2(128),
    city VARCHAR2(128),
    status VARCHAR2(128),
    last_node VARCHAR2(128),
    last_node_time DATE
);

-- 物流轨迹节点 (logistics_nodes)，主键：node_id
CREATE TABLE logistics_nodes (
    node_id NUMBER(10),
    order_id NUMBER(10),
    node_name VARCHAR2(128),
    node_time DATE
);

-- 仓库 (warehouses)，主键：warehouse_id
CREATE TABLE warehouses (
    warehouse_id NUMBER(10),
    warehouse_name VARCHAR2(128),
    city VARCHAR2(128),
    province VARCHAR2(128),
    region VARCHAR2(128)
);

-- 库存 (inventory)，主键：product_id, warehouse_id
CREATE TABLE inventory (
    product_id NUMBER(10),
    warehouse_id NUMBER(10),
    stock_qty NUMBER(10),
    quantity NUMBER(10),
    safety_stock NUMBER(10),
    safety_qty NUMBER(10)
);

-- 仓库库存快照 (wh_stock)，主键：warehouse_id, product_id
CREATE TABLE wh_stock (
    warehouse_id NUMBER(10),
    product_id NUMBER(10),
    stock_qty NUMBER(10),
    safety_stock NUMBER(10),
    safety_qty NUMBER(10),
    sku_cnt NUMBER(10)
);

-- 仓库出库流水 (wh_sales)，主键：warehouse_id, product_id, sale_date
CREATE TABLE wh_sales (
    warehouse_id NUMBER(10),
    product_id NUMBER(10),
    qty_sold NUMBER(10),
    amt_sold NUMBER(18,2),
    sale_date DATE
);

-- 购物车 (carts)，主键：cart_id
CREATE TABLE carts (
    cart_id NUMBER(10),
    customer_id NUMBER(10),
    product_id NUMBER(10),
    add_time DATE,
    quantity NUMBER(10),
    status VARCHAR2(128),
    is_purchased NUMBER(10)
);

-- 优惠券 (coupons)，主键：coupon_id
CREATE TABLE coupons (
    coupon_id NUMBER(10),
    coupon_name VARCHAR2(128),
    coupon_type VARCHAR2(128),
    promo_id NUMBER(10),
    face_value NUMBER(18,2),
    issued_cnt NUMBER(10),
    used_cnt NUMBER(10),
    order_id NUMBER(10),
    start_date DATE,
    end_date DATE,
    status VARCHAR2(128)
);

-- 订单用券 (order_coupon)，主键：order_id, coupon_id
CREATE TABLE order_coupon (
    order_id NUMBER(10),
    coupon_id NUMBER(10),
    promo_id NUMBER(10),
    coupon_cnt NUMBER(10),
    total_face NUMBER(18,2)
);

-- 促销活动 (promotions)，主键：promo_id
CREATE TABLE promotions (
    promo_id NUMBER(10),
    promo_name VARCHAR2(128),
    promo_type VARCHAR2(128),
    category_id NUMBER(10),
    budget NUMBER(18,2),
    start_date DATE,
    end_date DATE,
    discount_rate NUMBER(12,6)
);

-- 商品评价 (reviews)，主键：review_id
CREATE TABLE reviews (
    review_id NUMBER(10),
    order_id NUMBER(10),
    product_id NUMBER(10),
    customer_id NUMBER(10),
    rating NUMBER(10),
    content VARCHAR2(512),
    review_date DATE,
    created_at DATE
);

-- 用户行为埋点 (user_events)，主键：event_id
CREATE TABLE user_events (
    event_id NUMBER(10),
    customer_id NUMBER(10),
    session_id VARCHAR2(128),
    event_type VARCHAR2(128),
    event_time DATE,
    product_id NUMBER(10),
    page VARCHAR2(128),
    page_url VARCHAR2(512),
    device VARCHAR2(128)
);

-- 会员等级变更 (cust_level_log)，主键：log_id
CREATE TABLE cust_level_log (
    log_id NUMBER(10),
    customer_id NUMBER(10),
    old_level VARCHAR2(128),
    new_level VARCHAR2(128),
    change_date DATE,
    status VARCHAR2(128)
);

-- 分支行 (branches)，主键：branch_id
CREATE TABLE branches (
    branch_id NUMBER(10),
    branch_name VARCHAR2(128),
    city VARCHAR2(128),
    region VARCHAR2(128),
    open_date DATE,
    manager_id NUMBER(10)
);

-- 金融客户 (fin_customers)，主键：cust_id
CREATE TABLE fin_customers (
    cust_id NUMBER(10),
    cust_name VARCHAR2(128),
    cust_type VARCHAR2(128),
    gender VARCHAR2(128),
    birth_date DATE,
    city VARCHAR2(128),
    province VARCHAR2(128),
    register_date DATE,
    risk_level VARCHAR2(128),
    branch_id NUMBER(10),
    manager_id NUMBER(10),
    status VARCHAR2(128)
);

-- 账户 (accounts)，主键：account_id
CREATE TABLE accounts (
    account_id NUMBER(10),
    cust_id NUMBER(10),
    branch_id NUMBER(10),
    account_type VARCHAR2(128),
    balance NUMBER(18,2),
    acct_balance NUMBER(18,2),
    open_date DATE,
    status VARCHAR2(128),
    currency VARCHAR2(128)
);

-- 交易流水 (transactions)，主键：txn_id
CREATE TABLE transactions (
    txn_id NUMBER(10),
    account_id NUMBER(10),
    cust_id NUMBER(10),
    txn_date DATE,
    txn_type VARCHAR2(128),
    amount NUMBER(18,2),
    channel VARCHAR2(128),
    counterparty VARCHAR2(128),
    merchant VARCHAR2(128),
    mcc VARCHAR2(128),
    is_overseas NUMBER(10),
    city VARCHAR2(128),
    card_id NUMBER(10),
    balance_after NUMBER(18,2)
);

-- 银行卡 (cards)，主键：card_id
CREATE TABLE cards (
    card_id NUMBER(10),
    cust_id NUMBER(10),
    account_id NUMBER(10),
    card_type VARCHAR2(128),
    credit_limit NUMBER(18,2),
    open_date DATE,
    status VARCHAR2(128)
);

-- 卡交易 (card_txns)，主键：txn_id
CREATE TABLE card_txns (
    txn_id NUMBER(10),
    card_id NUMBER(10),
    txn_date DATE,
    amount NUMBER(18,2),
    merchant VARCHAR2(128),
    mcc VARCHAR2(128),
    is_overseas NUMBER(10),
    city VARCHAR2(128),
    status VARCHAR2(128)
);

-- 贷款 (loans)，主键：loan_id
CREATE TABLE loans (
    loan_id NUMBER(10),
    cust_id NUMBER(10),
    branch_id NUMBER(10),
    product_type VARCHAR2(128),
    loan_amount NUMBER(18,2),
    interest_rate NUMBER(12,6),
    term_months NUMBER(10),
    start_date DATE,
    end_date DATE,
    maturity_date DATE,
    status VARCHAR2(128),
    overdue_days NUMBER(10),
    outstanding NUMBER(18,2)
);

-- 还款流水 (repayments)，主键：repay_id
CREATE TABLE repayments (
    repay_id NUMBER(10),
    loan_id NUMBER(10),
    repay_date DATE,
    due_date DATE,
    amount NUMBER(18,2),
    due_amount NUMBER(18,2),
    paid_amount NUMBER(18,2),
    principal NUMBER(18,2),
    interest NUMBER(18,2),
    status VARCHAR2(128),
    overdue_days NUMBER(10)
);

-- 存款 (deposits)，主键：deposit_id
CREATE TABLE deposits (
    deposit_id NUMBER(10),
    cust_id NUMBER(10),
    branch_id NUMBER(10),
    account_id NUMBER(10),
    deposit_amt NUMBER(18,2),
    dep_amt NUMBER(18,2),
    amount NUMBER(18,2),
    rate NUMBER(12,6),
    avg_rate NUMBER(12,6),
    interest_rate NUMBER(12,6),
    term_months NUMBER(10),
    start_date DATE,
    maturity_date DATE,
    status VARCHAR2(128)
);

-- 信用评分 (credit_scores)，主键：score_id
CREATE TABLE credit_scores (
    score_id NUMBER(10),
    cust_id NUMBER(10),
    score NUMBER(10),
    score_date DATE,
    model_version VARCHAR2(128)
);

-- 风险事件 (risk_events)，主键：event_id
CREATE TABLE risk_events (
    event_id NUMBER(10),
    cust_id NUMBER(10),
    event_type VARCHAR2(128),
    risk_level VARCHAR2(128),
    risk_num NUMBER(10),
    event_date DATE,
    event_time DATE,
    amount NUMBER(18,2),
    status VARCHAR2(128)
);

-- 基金产品 (fund_products)，主键：fund_id
CREATE TABLE fund_products (
    fund_id NUMBER(10),
    fund_name VARCHAR2(128),
    fund_type VARCHAR2(128),
    manager_id NUMBER(10),
    manager_name VARCHAR2(128),
    launch_date DATE,
    risk_level VARCHAR2(128),
    status VARCHAR2(128)
);

-- 基金净值 (fund_nav)，主键：fund_id, nav_date
CREATE TABLE fund_nav (
    fund_id NUMBER(10),
    nav_date DATE,
    nav NUMBER(12,6),
    cur_nav NUMBER(12,6),
    acc_nav NUMBER(12,6)
);

-- 基金持仓 (holdings)，主键：hold_id
CREATE TABLE holdings (
    hold_id NUMBER(10),
    cust_id NUMBER(10),
    fund_id NUMBER(10),
    shares NUMBER(18,2),
    cost_amount NUMBER(18,2),
    market_value NUMBER(18,2),
    purchase_date DATE
);

-- 汇率 (fx_rates)，主键：rate_date, currency
CREATE TABLE fx_rates (
    rate_date DATE,
    currency VARCHAR2(128),
    base_currency VARCHAR2(128),
    rate NUMBER(12,6)
);

-- 财务报表 (fin_reports)，主键：report_id
CREATE TABLE fin_reports (
    report_id NUMBER(10),
    branch_id NUMBER(10),
    period VARCHAR2(7),
    report_type VARCHAR2(128),
    subject VARCHAR2(128),
    amount NUMBER(18,2),
    asset NUMBER(18,2),
    liability NUMBER(18,2),
    revenue NUMBER(18,2),
    cost NUMBER(18,2),
    profit NUMBER(18,2),
    loan_amt NUMBER(18,2),
    deposit_amt NUMBER(18,2)
);

-- 部门 (departments)，主键：dept_id
CREATE TABLE departments (
    dept_id NUMBER(10),
    dept_name VARCHAR2(128),
    parent_dept_id NUMBER(10),
    cost_center VARCHAR2(128),
    budget_cost NUMBER(18,2)
);

-- 员工 (employees)，主键：emp_id
CREATE TABLE employees (
    emp_id NUMBER(10),
    emp_name VARCHAR2(128),
    gender VARCHAR2(128),
    birth_date DATE,
    dept_id NUMBER(10),
    manager_id NUMBER(10),
    position VARCHAR2(128),
    job_level NUMBER(10),
    salary NUMBER(18,2),
    hire_date DATE,
    leave_date DATE,
    status VARCHAR2(128),
    city VARCHAR2(128),
    branch_id NUMBER(10)
);

-- 薪酬记录 (salaries)，主键：salary_id
CREATE TABLE salaries (
    salary_id NUMBER(10),
    emp_id NUMBER(10),
    base_salary NUMBER(18,2),
    bonus NUMBER(18,2),
    allowance NUMBER(18,2),
    total_salary NUMBER(18,2),
    effective_date DATE,
    pay_month VARCHAR2(7)
);

-- 考勤明细 (attendance)，主键：att_id
CREATE TABLE attendance (
    att_id NUMBER(10),
    emp_id NUMBER(10),
    att_date DATE,
    check_in DATE,
    check_out DATE,
    work_hours NUMBER(12,6),
    overtime_hours NUMBER(12,6),
    status VARCHAR2(128)
);

-- 休假记录 (leaves)，主键：leave_id
CREATE TABLE leaves (
    leave_id NUMBER(10),
    emp_id NUMBER(10),
    leave_type VARCHAR2(128),
    start_date DATE,
    end_date DATE,
    days NUMBER(10),
    status VARCHAR2(128)
);

-- 请假申请 (leave_requests)，主键：req_id
CREATE TABLE leave_requests (
    req_id NUMBER(10),
    emp_id NUMBER(10),
    leave_type VARCHAR2(128),
    start_date DATE,
    end_date DATE,
    days NUMBER(10),
    status VARCHAR2(128),
    apply_date DATE
);

-- 绩效考核 (performance)，主键：perf_id
CREATE TABLE performance (
    perf_id NUMBER(10),
    emp_id NUMBER(10),
    period VARCHAR2(7),
    score NUMBER(12,6),
    rating VARCHAR2(128),
    review_date DATE
);

-- 人事异动 (emp_changes)，主键：change_id
CREATE TABLE emp_changes (
    change_id NUMBER(10),
    emp_id NUMBER(10),
    change_type VARCHAR2(128),
    change_date DATE,
    old_dept_id NUMBER(10),
    new_dept_id NUMBER(10),
    old_salary NUMBER(18,2),
    new_salary NUMBER(18,2),
    old_position VARCHAR2(128),
    new_position VARCHAR2(128)
);

-- 培训记录 (training_records)，主键：record_id
CREATE TABLE training_records (
    record_id NUMBER(10),
    emp_id NUMBER(10),
    course_name VARCHAR2(128),
    train_date DATE,
    hours NUMBER(12,6),
    score NUMBER(12,6),
    cost NUMBER(18,2),
    status VARCHAR2(128)
);

-- 招聘需求 (recruitment)，主键：req_id
CREATE TABLE recruitment (
    req_id NUMBER(10),
    dept_id NUMBER(10),
    position VARCHAR2(128),
    headcount NUMBER(10),
    status VARCHAR2(128),
    channel VARCHAR2(128),
    open_date DATE,
    close_date DATE,
    apply_cnt NUMBER(10),
    offer_cnt NUMBER(10),
    hired_cnt NUMBER(10),
    offer_salary NUMBER(18,2),
    channel_cost NUMBER(18,2)
);

-- 项目 (projects)，主键：project_id
CREATE TABLE projects (
    project_id NUMBER(10),
    project_name VARCHAR2(128),
    dept_id NUMBER(10),
    start_date DATE,
    end_date DATE,
    budget NUMBER(18,2),
    cost NUMBER(18,2),
    revenue NUMBER(18,2),
    status VARCHAR2(128)
);

-- 项目成员投入 (project_assignments)，主键：assign_id
CREATE TABLE project_assignments (
    assign_id NUMBER(10),
    project_id NUMBER(10),
    emp_id NUMBER(10),
    allocation_pct NUMBER(12,6),
    role VARCHAR2(128)
);

-- 工资单 (payroll)，主键：payroll_id
CREATE TABLE payroll (
    payroll_id NUMBER(10),
    emp_id NUMBER(10),
    dept_id NUMBER(10),
    pay_month VARCHAR2(7),
    pay_date DATE,
    gross_pay NUMBER(18,2),
    net_pay NUMBER(18,2),
    tax NUMBER(18,2),
    social_insurance NUMBER(18,2),
    pay_amount NUMBER(18,2),
    pay_method VARCHAR2(128)
);

